656.     // Proofs
657.     ////////////////////////////////////////////////////////////////////////////////////////////////
658. 
659.     #[inductive(initialize)]
660.     fn initialize_inductive(post: Self, buffer_size: nat, num_replicas: nat, contents: Map<int, StoredType<DT>>, cell_ids: Seq<CellId>,  unbounded_log_instance: UnboundedLog::Instance<DT>, ) {
661.         assert forall |i| post.tail <= i < post.buffer_size implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
662.             int_mod_less_than_same(i, post.buffer_size as int);
663.         }
664.     }
665. 
666.     #[inductive(advance_head_start)]
667.     fn advance_head_start_inductive(pre: Self, post: Self, node_id: NodeId) { }
