676.     fn advance_head_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
677.         assert(pre.pointer_ordering());
678.         assert(pre.pointer_differences());
679.         assert(pre.complete());
680.         assert(pre.all_combiner_valid());
681.         assert(pre.combiner.contains_key(node_id));
682.         assert(pre.combiner[node_id].is_AdvancingHead());
683.         let idx = pre.combiner[node_id].get_AdvancingHead_idx();
684.         let min_local_version = pre.combiner[node_id].get_AdvancingHead_min_local_version();
685.         assert(idx == pre.num_replicas);
686.         map_min_value_smallest(pre.local_versions, (pre.num_replicas - 1) as nat);
687.         assert(min_local_version <= pre.local_versions[0]);
688.     }
