1. // SPDX-License-Identifier: Apache-2.0 OR MIT
2. //
3. // Self-contained adaptation of verified-node-replication/src/spec/cyclicbuffer.rs.
4. // All dependencies required by the cyclic-buffer specification are inlined below.
5. 
6. fn main() {}
7. 
8. #[allow(unused_imports)]
9. use verus_builtin::*;
10. use verus_builtin_macros::*;
11. use verus_state_machines_macros::*;
12. use vstd::cell::{CellId, PointsTo};
13. use vstd::prelude::*;
14. 
15. verus! {
16. 
17. pub type NodeId = nat;
18. pub type LogIdx = nat;
19. 
20. #[verus::trusted]
21. pub trait Dispatch: Sized {
22.     type WriteOperation: Sized + Send;
23. }
24. 
25. pub tracked struct LogEntry<DT: Dispatch> {
26.     pub op: DT::WriteOperation,
27.     pub node_id: NodeId,
28. }
29. 
30. pub struct ConcreteLogEntry<DT: Dispatch> {
31.     pub op: DT::WriteOperation,
32.     pub node_id: u64,
33. }
34. 
35. pub open const LOG_SIZE: usize = 512 * 1024;
36. 
37. pub open spec fn map_contains_value<K, V>(map: Map<K, V>, val: V) -> bool {
38.     exists|i: K| #[trigger] map.contains_key(i) && map.index(i) == val
39. }
40. 
41. #[verifier(nonlinear)]
42. #[verifier::external_body]
43. pub proof fn int_mod_less_than_same(i: int, len: int)
44.     requires 0 <= i < len, len > 0,
45.     ensures (i % len) == i,
46. { unimplemented!() }
47. 
48. }
49. 
50. // Minimal interface inlined from spec/unbounded_log.rs. CyclicBuffer only uses
51. // UnboundedLog::Instance and the sharded log entry projection.
52. tokenized_state_machine! {
53. UnboundedLog<DT: Dispatch> {
54.     fields {
55.         #[sharding(map)]
56.         pub log: Map<LogIdx, LogEntry<DT>>,
57.     }
58. 
59.     init! {
60.         initialize() {
61.             init log = Map::empty();
62.         }
63.     }
64. }
65. }
66. 
67. ////////////////////////////////////////////////////////////////////////////////////////////////////
68. //
69. // Cyclic Buffer
70. // =============
71. //
72. // The cyclic buffer is a bounded log with multiple readers and writers. A writer will check whether
73. // there's enough space in the log and the reserve space to place its update operations into the log.
74. // Log space can be reclaimed once all readers have advanced their read pointers accordingly.
75. //
76. ////////////////////////////////////////////////////////////////////////////////////////////////////
77. 
78. verus! {
79. 
80. /// Logical Log Index
81. ///
82. /// In contrast to the unbounded log, the log entries can be "negative". This is used for the
83. /// initialization where all entries are initialized with the range [-LOG_SIZE, 0)
84. pub type LogicalLogIdx = int;
85. 
86. /// The size of the log. XXX: can we get rid of this?
87. 
88. /// An entry in the log
89. ///
